CustomField.formula:
IF(NOT(ISBLANK(EstudioOportunidad__c)),
IF(CreatedDate > EstudioOportunidad__r.CreatedDate,
"AGREGADO " + TEXT(DAY(DATEVALUE(CreatedDate))) + '/' + TEXT(MONTH(DATEVALUE(CreatedDate))) + '/' + TEXT(YEAR(DATEVALUE(CreatedDate))),
IF(LastModifiedDate > EstudioOportunidad__r.CreatedDate,
"MODIFICADO " + TEXT(DAY(DATEVALUE(LastModifiedDate))) + '/' + TEXT(MONTH(DATEVALUE(LastModifiedDate))) + '/' + TEXT(YEAR(DATEVALUE(LastModifiedDate))),
"-"
)
),
"-"
)
